package ncasa.expense.application.forecast;
import java.math.BigDecimal;import java.time.*;import java.util.*;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;
public final class ForecastExpensePlansUseCase{private final ExpensePlanRepository plans;private final HouseholdExpenseAccessPort access;private final Clock clock;public ForecastExpensePlansUseCase(ExpensePlanRepository p,HouseholdExpenseAccessPort a,Clock c){plans=p;access=a;clock=c;}public ExpensePlanForecast execute(Long actor,UUID householdId,LocalDate rawFrom,LocalDate rawTo){var h=new HouseholdRef(householdId);access.getContext(h,actor);LocalDate from=rawFrom==null?LocalDate.now(clock):rawFrom,to=rawTo==null?from.plusDays(90):rawTo;if(from.isAfter(to)||to.isAfter(from.plusMonths(12)))throw new IllegalArgumentException("Forecast range must be at most 12 months");var occurrences=new ArrayList<ExpensePlanForecast.Occurrence>();for(var p:plans.findActiveForForecast(h))project(p,from,to,occurrences);occurrences.sort(Comparator.comparing(ExpensePlanForecast.Occurrence::occurrenceDate).thenComparing(ExpensePlanForecast.Occurrence::planId));var totals=new TreeMap<String,BigDecimal>();occurrences.forEach(o->totals.merge(o.currency(),o.amount(),BigDecimal::add));return new ExpensePlanForecast(householdId,from,to,totals.entrySet().stream().map(e->new ExpensePlanForecast.CurrencyTotal(e.getKey(),e.getValue())).toList(),occurrences);}
 private void project(ExpensePlan p,LocalDate from,LocalDate to,List<ExpensePlanForecast.Occurrence> result){long cursor=p.scheduleCursor();int projected=0;while(true){LocalDate date;try{date=p.schedule().occurrence(cursor);}catch(IllegalArgumentException e){break;}long endIndex="AFTER_OCCURRENCES".equals(p.endCondition().type())?p.materializedOccurrences()+projected:cursor;if(!p.endCondition().allows(date,endIndex)||date.isAfter(to))break;if(!date.isBefore(from)){var split=p.template().split().materialize(p.template().total());boolean last=last(p,cursor,p.materializedOccurrences()+projected,date);result.add(new ExpensePlanForecast.Occurrence(p.id().value(),date.toString(),date,p.template().description().value(),p.template().total().amount(),p.template().total().currency(),p.template().payerMemberId().value(),p.template().categoryId()==null?null:p.template().categoryId().value(),split.allocations().stream().map(a->new ExpensePlanForecast.Allocation(a.memberId().value(),a.amount().amount())).toList(),last));projected++;}cursor++;if(p.schedule().frequency()==ExpensePlanFrequency.ONCE)break;}}
 private boolean last(ExpensePlan p,long cursor,int materialized,LocalDate date){if(p.schedule().frequency()==ExpensePlanFrequency.ONCE)return true;if("AFTER_OCCURRENCES".equals(p.endCondition().type()))return materialized+1>=p.endCondition().occurrenceLimit();return !p.endCondition().allows(p.schedule().occurrence(cursor+1),cursor+1);}}
